package com.chubb.apac.claims.modulith.user.service;
import com.chubb.apac.claims.modulith.common.exception.*;import com.chubb.apac.claims.modulith.common.security.JwtService;import com.chubb.apac.claims.modulith.user.dto.request.*;import com.chubb.apac.claims.modulith.user.model.User;import com.chubb.apac.claims.modulith.user.repository.UserRepository;import com.chubb.apac.claims.modulith.user.service.impl.AuthServiceImpl;import org.junit.jupiter.api.*;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;import org.mockito.junit.jupiter.MockitoExtension;import org.springframework.security.crypto.password.PasswordEncoder;import java.util.Optional;import static org.assertj.core.api.Assertions.*;import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class AuthServiceImplTest {@Mock UserRepository users;@Mock PasswordEncoder passwords;@Mock JwtService jwt;@Mock TokenRevocationService revocations;AuthServiceImpl service;@BeforeEach void setUp(){service=new AuthServiceImpl(users,passwords,jwt,revocations);}
 @Test void registersClaimant(){when(users.existsByEmailIgnoreCase("a@b.com")).thenReturn(false);when(passwords.encode("password1")).thenReturn("hash");when(jwt.generate(any())).thenReturn("token");var r=service.register(new RegisterClaimantRequest("A@B.COM","password1","Alex",null));assertThat(r.email()).isEqualTo("a@b.com");verify(users).save(any(User.class));}
 @Test void rejectsDuplicate(){when(users.existsByEmailIgnoreCase("a@b.com")).thenReturn(true);assertThatThrownBy(()->service.register(new RegisterClaimantRequest("a@b.com","password1","Alex",null))).isInstanceOf(ConflictException.class);}
 @Test void rejectsBadPassword(){User u=new User();u.setActive(true);when(users.findByEmailIgnoreCase("a@b.com")).thenReturn(Optional.of(u));when(passwords.matches("bad",null)).thenReturn(false);assertThatThrownBy(()->service.login(new LoginRequest("a@b.com","bad"))).isInstanceOf(UnauthorizedException.class);}}
